#include <cstdlib>
#include <iostream>

struct Resource {
    ~Resource() { std::cerr << "Resource destroyed!\n"; }
};

void cleanup_handler() {
    std::cout << "atexit handler called.\n";
}

void terminate_example(bool immediate) {
    Resource r; // Local object
    if (immediate) {
        std::abort(); // No cleanup, no destructor call
    }
    // atexit(cleanup_handler);
    // std::exit(EXIT_FAILURE); // Static cleanup occurs, but NOT local destructor (r)
}

int main() {
    atexit(cleanup_handler);
    // terminate_example(false); // If called, exit() cleans statics/buffers, but not 'r'.
    // If main returns normally, all cleanup occurs.
    return EXIT_SUCCESS;
}
